import sqlite3
import subprocess
from langchain_core.tools import tool

DB_PATH = "/var/wms/inventory.db"
LABEL_SCRIPT = "/opt/wms/scripts/print_putaway_labels.sh"


@tool
def transfer_stock_and_run_putaway_job(sku: str, from_bin: str, to_bin: str, quantity: int) -> str:
    if not sku or not from_bin or not to_bin:
        return "error: sku, from_bin and to_bin are required"
    if from_bin == to_bin:
        return "error: source and destination bins must differ"
    if quantity <= 0:
        return "error: quantity must be positive"
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT qty FROM bin_stock WHERE sku = ? AND bin = ?", (sku, from_bin)
        ).fetchone()
        if row is None or row[0] < quantity:
            return "error: insufficient stock in source bin"
        dest = conn.execute("SELECT 1 FROM bins WHERE code = ?", (to_bin,)).fetchone()
        if dest is None:
            return "error: destination bin does not exist"
        conn.execute(
            "UPDATE bin_stock SET qty = qty - ? WHERE sku = ? AND bin = ?",
            (quantity, sku, from_bin),
        )
        conn.execute(
            "INSERT INTO bin_stock (sku, bin, qty) VALUES (?, ?, ?) "
            "ON CONFLICT(sku, bin) DO UPDATE SET qty = qty + excluded.qty",
            (sku, to_bin, quantity),
        )
        conn.commit()
    finally:
        conn.close()
    result = subprocess.run(
        [LABEL_SCRIPT, sku, to_bin, str(quantity)], capture_output=True, text=True
    )
    if result.returncode != 0:
        return "moved stock but label job failed: " + result.stderr.strip()
    return f"moved {quantity} of {sku} from {from_bin} to {to_bin}; labels printed"

import sqlite3
from langchain_core.tools import tool

DB_PATH = "/var/wms/inventory.db"
VALID_ZONES = {"A", "B", "C", "COLD", "HAZ"}


@tool
def move_pallet_to_zone(pallet_id: str, zone: str, slot: str) -> str:
    if not pallet_id.strip():
        return "error: pallet_id is required"
    if zone not in VALID_ZONES:
        return "error: unknown zone " + zone
    if not slot.strip():
        return "error: slot is required"
    conn = sqlite3.connect(DB_PATH)
    try:
        pallet = conn.execute(
            "SELECT zone, slot FROM pallets WHERE id = ?", (pallet_id,)
        ).fetchone()
        if pallet is None:
            return "error: pallet not found"
        taken = conn.execute(
            "SELECT 1 FROM pallets WHERE zone = ? AND slot = ? AND id != ?",
            (zone, slot, pallet_id),
        ).fetchone()
        if taken:
            return "error: slot already occupied"
        conn.execute(
            "UPDATE pallets SET zone = ?, slot = ? WHERE id = ?",
            (zone, slot, pallet_id),
        )
        conn.commit()
    finally:
        conn.close()
    return f"pallet {pallet_id} moved from {pallet[0]}-{pallet[1]} to {zone}-{slot}"
